"""Source-bound saved analysis for the exact C125763 subsection-1 cases."""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path

from saved_crossing import SOURCES, measure

CAMERAS = ('overview', 'approach', 'reference_corner', 'driver_reference')


def _sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def _required(root, name):
    path = Path(root) / name
    if not path.is_file() or path.is_symlink():
        raise ValueError('Missing required source: ' + name)
    return path


def _sources(root):
    root = Path(root)
    if not (root / 'source-manifest.json').exists():
        alias = _required(root, 'original-source-manifest.json')
        if (root / 'fixture-provenance.json').is_file():
            provenance = json.loads((root / 'fixture-provenance.json').read_text())
            if provenance.get('diagnostic_fixture') is not True or provenance.get('physical_acceptance_claimed') is not False:
                raise ValueError('Diagnostic source provenance is incomplete')
        else:
            seal = json.loads(_required(root, 'capture-seal.json').read_text())
            if seal.get('provenance_kind') != 'native' or seal.get('sources', {}).get('original-source-manifest.json') != _sha(alias):
                raise ValueError('Native source manifest alias is not sealed')
        (root / 'source-manifest.json').write_bytes(alias.read_bytes())
    source = json.loads(_required(root, 'source-manifest.json').read_text())
    paths = {}
    for name in SOURCES:
        path = _required(root, name)
        if source.get(name, {}).get('kind') != 'original_native' or source[name].get('sha256') != _sha(path):
            raise ValueError('Original source hash mismatch: ' + name)
        paths[name] = path
    return paths


def measure_crossing_source(root):
    paths = _sources(root)
    timing = measure(root)
    site = json.loads(paths['site-context.json'].read_text())
    return {'site': site, 'timing': timing, 'paths': paths}


def measure_other_first_entry(root):
    timing = measure_crossing_source(root)['timing']
    return {'other_entered_before_ego': timing['other_entered_before_ego'],
            'other_entry': timing['other_entry'], 'ego_entry': timing['ego_entry']}


def measure_clearance_response(root):
    timing = measure_crossing_source(root)['timing']
    return {'other_cleared_before_ego_entry': timing['other_cleared_before_ego_entry'],
            'other_exit': timing['other_exit'], 'ego_entry': timing['ego_entry'],
            'simultaneous_body_overlap_frames': timing['simultaneous_body_overlap_frames']}


def source_device_context(root):
    value = measure_crossing_source(root)
    site = value['site']
    return {'official_yield_sign_present': site['official_yield_sign_present'],
            'yield_sign_controls_intersection': site['yield_sign_controls_intersection'],
            'subsection_4_reviewed': site['subsection_4_reviewed'],
            'legal_applicability': 'unresolved_subsection_4_and_device_exception'}


def source_opposing_exception(root):
    site = measure_crossing_source(root)['site']
    return {'approach_relation': site['approach_relation'],
            'ego_highway': site['ego_highway'], 'other_highway': site['other_highway'],
            'ego_side': site['ego_side'], 'other_side': site['other_side'],
            'opposing_left_turn_exception_observed': False}


METHODS = {'crossing_source': measure_crossing_source,
           'other_first_entry': measure_other_first_entry,
           'clearance_response': measure_clearance_response,
           'device_context': source_device_context,
           'opposing_exception': source_opposing_exception}


def analyze(attempt, output):
    root = Path(attempt)
    config = json.loads(_required(root, 'config.json').read_text())
    construction = json.loads(_required(root, 'construction.json').read_text())
    case_id = config['selected_case_id']
    if construction['case_id'] != case_id:
        raise ValueError('Selected construction case differs')
    paths = _sources(root)
    hashes = {name: _sha(path) for name, path in paths.items()}
    crossing = measure_crossing_source(root)
    timing = crossing['timing']
    if timing['case_id'] != case_id or not timing['other_entered_before_ego']:
        raise ValueError('Selected original crossing identity/order differs')
    if timing['other_cleared_before_ego_entry'] != case_id.endswith('__precedence'):
        raise ValueError('Selected original clearance response differs')
    values = {'crossing_source': {'cell_id': crossing['site']['cell_id'],
                                 'crossing_id': timing['crossing_id'],
                                 'ego_highway': crossing['site']['ego_highway'],
                                 'other_highway': crossing['site']['other_highway']},
              'other_first_entry': measure_other_first_entry(root),
              'clearance_response': measure_clearance_response(root),
              'device_context': source_device_context(root),
              'opposing_exception': source_opposing_exception(root)}
    method_names = {'crossing_source': 'measure_crossing_source',
                    'other_first_entry': 'measure_other_first_entry',
                    'clearance_response': 'measure_clearance_response',
                    'device_context': 'source_device_context',
                    'opposing_exception': 'source_opposing_exception'}
    measurements = {key: {'method': method_names[key], 'value': value,
                          'sources': hashes} for key, value in values.items()}
    report = {'format': 'worker-analysis-report', 'case_id': case_id,
              'measurements': measurements,
              'diagnostic_fixture': (root / 'fixture-provenance.json').is_file(),
              'legal_verdict_claimed': False,
              'limitations': ['Yield-sign control and subsection-4 applicability remain source-review questions.',
                              'Original-footprint order is a measurement, not a legal verdict.']}
    recording = construction['recording_description']
    channel_root = root / 'channels'
    channel_root.mkdir(exist_ok=False)
    ego = [json.loads(line) for line in paths['ego-body-history.jsonl'].read_text().splitlines()]
    evidence = []
    channel_values = {'other_entry_and_clearance_brackets': values['clearance_response'],
                      'original_body_footprint': {'source_sha256': hashes['ego-body-history.jsonl']},
                      'original_four_camera_pixels': {'source_sha256': _sha(_required(root, 'video_frames.jsonl'))}}
    for channel in recording['channels']:
        name = channel['name']
        if name not in channel_values:
            raise ValueError('Unexpected selected channel: ' + name)
        path = channel_root / (name + '.jsonl')
        path.write_text(''.join(json.dumps({'time_s': row['time_s'], 'value': channel_values[name]}) + '\n'
                                for row in ego))
        evidence.append({'name': name, 'unit': channel['unit'],
                         'reference': str(path.relative_to(root))})
    for context in recording['context_inputs']:
        name = context['name']
        if name not in ('reviewed_site_device_highway_packet', 'reviewed_original_context'):
            raise ValueError('Unexpected selected context: ' + name)
        path = channel_root / (name + '.json')
        path.write_text(json.dumps({name: {'site': crossing['site'], 'sources': hashes}}) + '\n')
        evidence.append({'name': name, 'unit': context['unit'],
                         'reference': str(path.relative_to(root))})
    projected = root / 'crossing_history.jsonl'
    projected_text = ''.join(json.dumps({'frame': row['frame'], 'time_s': row['time_s'],
        'ego_vertices_m': [[x, y, 0.0] for x, y in row['body_vertices_xy_m']]}) + '\n'
        for row in ego)
    if projected.exists():
        if projected.read_text() != projected_text:
            raise ValueError('Projected crossing history differs from original bodies')
    else:
        projected.write_text(projected_text)
    result = {'case_id': case_id, 'measured_values': values,
              'target_checks': [{'target': 'source-bound other-first entry and ego clearance response',
                'requested': config['case']['physical_target'],
                'measured': values['clearance_response'], 'method': 'measure_clearance_response',
                'tolerance': 0, 'matched': True, 'physical_cause_confirmed': False,
                'cause_evidence': hashes}],
              'setup_confirmed': False, 'behavior_attempted': False,
              'maneuver_completed': False, 'termination_reason': 'Saved original review pending',
              'physical_failure_flags': [], 'trace_reference': 'trace.jsonl',
              'video_references': [name + '.mkv' for name in CAMERAS],
              'video_frame_map_reference': 'video_frames.jsonl',
              'recording_description': recording, 'recording_evidence': evidence,
              'realized_observables': {}, 'legal_judgment': None,
              'physical_acceptance_claimed': False}
    (root / 'result.json').write_text(json.dumps(result, indent=2) + '\n')
    Path(output).write_text(json.dumps(report, indent=2) + '\n')
    return report


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--attempt', required=True)
    parser.add_argument('--output', required=True)
    args = parser.parse_args()
    print(analyze(args.attempt, args.output)['case_id'])


if __name__ == '__main__':
    main()

"""Lazy Native body sampler and vehicle control for the C125763 pair.

Placement/routes must be obtained from a separately reviewed real map. A requested
response mode is never reported as realized crossing behavior without saved audit.
"""
from __future__ import annotations

import math


def body_row(snapshot, actor):
    if not actor.is_alive:
        raise ValueError("original Native actor is dead")
    frame, time_s = snapshot.frame, snapshot.timestamp.elapsed_seconds
    if type(frame) is not int or type(time_s) not in (int, float) or not math.isfinite(time_s):
        raise ValueError("invalid original Native frame/time")
    vertices = actor.bounding_box.get_world_vertices(actor.get_transform())
    if len(vertices) < 4:
        raise ValueError("original Native bounding box missing")
    points = set()
    for p in vertices:
        if not all(math.isfinite(v) for v in (p.x, p.y, p.z)):
            raise ValueError("nonfinite original Native body vertex")
        points.add((float(p.x), float(p.y)))
    if len(points) < 4:
        raise ValueError("degenerate original Native body footprint")
    points = sorted(points)
    def cross(a, b, c):
        return (b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])
    lower, upper = [], []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    hull = lower[:-1]+upper[:-1]
    if len(hull) < 3:
        raise ValueError("degenerate original Native body hull")
    return {"frame": frame, "time_s": time_s, "actor_id": actor.id,
            "body_vertices_xy_m": [list(p) for p in hull]}


def capture_pair(snapshot, actors, streams):
    """Write one original frame per actor, synchronized to one completed world tick."""
    import json
    if set(actors) != {"ego", "other"} or set(streams) != {"ego", "other"} or \
            actors["ego"].id == actors["other"].id:
        raise ValueError("two distinct original Native actors and streams required")
    rows = {name: body_row(snapshot, actors[name]) for name in ("ego", "other")}
    for name in ("ego", "other"):
        streams[name].write(json.dumps(rows[name], allow_nan=False)+"\n")
    return rows


def control_step(carla, actor, route, *, hold, target_speed_mps=5.0):
    """Hold or follow a reviewed route with bounded actuation; never teleport."""
    if not isinstance(hold, bool):
        raise ValueError("explicit response control state required")
    if hold:
        actor.apply_control(carla.VehicleControl(throttle=0.0, brake=1.0, steer=0.0))
        return "held"
    if len(route) < 2 or any(len(point) != 3 or not all(math.isfinite(v) for v in point)
                             for point in route):
        raise ValueError("reviewed route requires finite 3D points")
    if not math.isfinite(target_speed_mps) or not 0 < target_speed_mps <= 20:
        raise ValueError("bounded engineering target speed required")
    location = actor.get_location()
    velocity = actor.get_velocity()
    speed = math.sqrt(velocity.x**2+velocity.y**2+velocity.z**2)
    target = min(route[1:], key=lambda p: math.hypot(p[0]-location.x, p[1]-location.y))
    desired = math.atan2(target[1]-location.y, target[0]-location.x)
    current = math.radians(actor.get_transform().rotation.yaw)
    error = math.atan2(math.sin(desired-current), math.cos(desired-current))
    steer = max(-1.0, min(1.0, error/.5))
    throttle = max(0.0, min(.55, .25*(target_speed_mps-speed)))
    brake = max(0.0, min(.8, .2*(speed-target_speed_mps)))
    actor.apply_control(carla.VehicleControl(throttle=throttle, brake=brake, steer=steer))
    return "released"

import hashlib
import json
from pathlib import Path
import sys
import tempfile
import unittest
from types import SimpleNamespace as NS


PACKAGE = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(PACKAGE))
from native_run import CAMERAS, run


class Carla:
    @staticmethod
    def Location(**values):
        return NS(**values)

    @staticmethod
    def Rotation(**values):
        return NS(**values)

    @staticmethod
    def Transform(location, rotation):
        return NS(location=location, rotation=rotation)

    @staticmethod
    def VehicleControl(**values):
        return NS(**values)


class Blueprint:
    def __init__(self, name):
        self.id = name
        self.attributes = {}

    def set_attribute(self, name, value):
        self.attributes[name] = value


class Library:
    def find(self, name):
        return Blueprint(name)


class Box:
    def get_world_vertices(self, transform):
        x, y = transform.location.x, transform.location.y
        return [NS(x=x + dx, y=y + dy, z=z) for dx in (-.4, .4)
                for dy in (-.4, .4) for z in (-.5, .5)]


class Vehicle:
    bounding_box = Box()

    def __init__(self, actor_id, transform):
        self.id = actor_id
        self.transform = transform
        self.destroyed = False
        self.controls = []

    def get_transform(self):
        return self.transform

    def get_location(self):
        return self.transform.location

    def get_velocity(self):
        return NS(x=0, y=0, z=0)

    def apply_control(self, control):
        self.controls.append(control)

    def destroy(self):
        self.destroyed = True


class Sensor:
    def __init__(self, blueprint):
        self.width = int(blueprint.attributes['image_size_x'])
        self.height = int(blueprint.attributes['image_size_y'])
        self.callback = None
        self.stopped = False
        self.destroyed = False

    def listen(self, callback):
        self.callback = callback

    def stop(self):
        self.stopped = True

    def destroy(self):
        self.destroyed = True


class Map:
    def to_opendrive(self):
        return '<OpenDRIVE/>\n'

    def get_waypoint(self, location, project_to_road=False):
        return NS(road_id=1 if location.y == 0 else 2, lane_id=1)


class World:
    def __init__(self):
        self.map = Map()
        self.settings = NS(synchronous_mode=False, fixed_delta_seconds=None)
        self.frame = 99
        self.vehicles = []
        self.sensors = []
        self.fail_camera = False
        self.bad_camera_time = False

    def get_map(self):
        return self.map

    def get_settings(self):
        return self.settings

    def apply_settings(self, settings):
        self.settings = NS(**vars(settings))

    def get_blueprint_library(self):
        return Library()

    def try_spawn_actor(self, blueprint, transform):
        actor = Vehicle(len(self.vehicles) + 1, transform)
        self.vehicles.append(actor)
        return actor

    def spawn_actor(self, blueprint, transform, attach_to=None):
        if self.fail_camera and len(self.sensors) == 2:
            return None
        sensor = Sensor(blueprint)
        self.sensors.append(sensor)
        return sensor

    def tick(self):
        self.frame += 1
        for sensor in self.sensors:
            if sensor.callback:
                sensor.callback(NS(frame=self.frame,
                                   timestamp=(self.frame - 99) * .05 +
                                   (.01 if self.bad_camera_time else 0),
                                   width=sensor.width, height=sensor.height,
                                   raw_data=bytes([0, 0, 255, 255]) *
                                   sensor.width * sensor.height))
        return self.frame

    def get_snapshot(self):
        return NS(frame=self.frame,
                  timestamp=NS(elapsed_seconds=(self.frame - 99) * .05))


class NativeRunTest(unittest.TestCase):
    def setUp(self):
        scratch = PACKAGE.parents[1] / '.runtime-work' / 'c125763-native-run-tests'
        scratch.mkdir(parents=True, exist_ok=True)
        self.temp = tempfile.TemporaryDirectory(dir=scratch)
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)
        self.world = World()
        scene = {
            'assignment_id': 'testing__C125763__NRS-484B-250-1__motor_vehicle_driver',
            'review_status': 'diagnostic_fixture',
            'map_sha256': hashlib.sha256(self.world.map.to_opendrive().encode()).hexdigest(),
            'reviewer': 'fixture', 'map_source_citation': 'fixture only',
            'highway_source_citation': 'fixture only',
            'device_source_citation': 'fixture only',
            'subsection_4_source_citation': 'NRS 484B.250(4) exported text',
            'cell_id': 'C125763', 'control': 'yield_sign', 'maneuver': 'travel',
            'ego_highway': 'A', 'other_highway': 'B',
            'approach_relation': 'crossing', 'ego_side': 'left', 'other_side': 'right',
            'crossing_id': 'fixture crossing', 'roadway_id': 'fixture roadway',
            'intersection_polygon_xy_m': [[-1, -1], [1, -1], [1, 1], [-1, 1]],
            'official_yield_sign_present': True,
            'yield_sign_controls_intersection': True,
            'subsection_4_reviewed': False,
            'ego_route': [[-5, 0, 0], [2, 0, 0]],
            'other_route': [[0, -5, 0], [0, 2, 0]],
            'ego_lane': {'road_id': 1, 'lane_id': 1},
            'other_lane': {'road_id': 2, 'lane_id': 1},
            'ego_blueprint': 'vehicle.ego', 'other_blueprint': 'vehicle.other',
            'release_s': {'precedence': .1, 'advance': 0},
            'other_release_s': .1,
            'camera_dimensions': {name: [2, 2] for name in CAMERAS},
            'camera_poses': {name: dict(x=0, y=0, z=5, pitch=-30, yaw=0, roll=0)
                             for name in CAMERAS},
            'camera_mounts': {name: ('ego' if name == 'driver_reference' else 'world')
                              for name in CAMERAS},
        }
        for name in ('device', 'highway'):
            path = self.root / (name + '.txt')
            path.write_text('fixture ' + name + '\n')
            scene[name + '_source'] = {'path': path.name,
                                       'sha256': hashlib.sha256(path.read_bytes()).hexdigest(),
                                       'citation': 'fixture only'}
        self.packet = self.root / 'reviewed-site.json'
        self.packet.write_text(json.dumps(scene) + '\n')

    def test_same_tick_cameras_controls_and_release(self):
        output = self.root / 'capture'
        receipt = run(self.world, Carla, self.packet, output, 'precedence',
                      frame_count=3, diagnostic_fixture=True)
        self.assertEqual(receipt['camera_view_frames'], 12)
        self.assertEqual(len(self.world.vehicles[0].controls), 3)
        self.assertEqual([control.brake for control in self.world.vehicles[0].controls],
                         [1.0, 1.0, 0.0])
        self.assertTrue(all(actor.destroyed for actor in self.world.vehicles))
        self.assertTrue(all(sensor.stopped and sensor.destroyed for sensor in self.world.sensors))
        self.assertFalse(self.world.settings.synchronous_mode)
        self.assertTrue((output / 'source-manifest.json').is_file())

    def test_partial_sensor_spawn_restores_owned_resources(self):
        self.world.fail_camera = True
        with self.assertRaisesRegex(RuntimeError, 'camera spawn failed'):
            run(self.world, Carla, self.packet, self.root / 'failed',
                'precedence', frame_count=3, diagnostic_fixture=True)
        self.assertTrue(all(actor.destroyed for actor in self.world.vehicles))
        self.assertTrue(all(sensor.stopped and sensor.destroyed for sensor in self.world.sensors))
        self.assertFalse(self.world.settings.synchronous_mode)

    def test_fixture_cannot_be_published_as_original(self):
        with self.assertRaisesRegex(ValueError, 'reviewed original'):
            run(self.world, Carla, self.packet, self.root / 'unreviewed',
                'precedence', frame_count=3)
        self.assertEqual(self.world.vehicles, [])

    def test_camera_timestamp_failure_restores_world(self):
        self.world.bad_camera_time = True
        with self.assertRaisesRegex(ValueError, 'timestamp differs'):
            run(self.world, Carla, self.packet, self.root / 'bad-time',
                'precedence', frame_count=3, diagnostic_fixture=True)
        self.assertTrue(all(actor.destroyed for actor in self.world.vehicles))
        self.assertTrue(all(sensor.stopped and sensor.destroyed for sensor in self.world.sensors))
        self.assertFalse(self.world.settings.synchronous_mode)

    def test_original_requires_full_four_view_profile(self):
        scene = json.loads(self.packet.read_text())
        scene['review_status'] = 'reviewed_original'
        self.packet.write_text(json.dumps(scene) + '\n')
        with self.assertRaisesRegex(ValueError, '900 frames and four profile cameras'):
            run(self.world, Carla, self.packet, self.root / 'too-small',
                'precedence', frame_count=900)
        self.assertEqual(self.world.vehicles, [])


if __name__ == '__main__':
    unittest.main()

